function fallbackTableLiveRow(tableNumber: string): TableLiveRow {
  return {
    tableNumber,
    tableLabel: `Meja ${tableNumber}`,
    status: "empty",
    currentOrderId: null,
    orderNo: null,
    customerName: null,
    customerPhone: null,
    total: 0,
    timerMinutes: 0,
    kitchenStatus: null,
    needsCleaning: false,
    lastStatusAt: null,
  };
}

function tableLiveStatusLabel(table: TableLiveRow | null | undefined) {
  if (!table) return "Belum sinkron";
  if (table.needsCleaning || table.status === "needs_cleaning") return "Perlu dibersihkan";
  if (table.status === "empty") return "Kosong";
  if (table.status === "paid") return "Lunas";
  if (
    table.status === "pending" ||
    table.status === "accepted" ||
    table.status === "awaiting_payment" ||
    table.status === "ready"
  ) {
    return "Belum Bayar";
  }
  if (occupiedTableStatuses.has(table.status)) return "Terisi";
  return table.status.replace(/_/g, " ");
}

function tableLiveStatusTone(table: TableLiveRow | null | undefined) {
  if (!table) return "border-[#4a4a54] bg-white/[0.06] text-[#d4d4d8]";
  if (table.needsCleaning || table.status === "needs_cleaning") {
    return "border-[#d11a2a]/45 bg-[#d11a2a]/12 text-[#ffc2c8]";
  }
  if (table.status === "empty") return "border-[#22c55e]/45 bg-[#22c55e]/12 text-[#dcfce7]";
  if (table.status === "paid") return "border-[#22c55e]/45 bg-[#22c55e]/12 text-[#dcfce7]";
  if (
    table.status === "pending" ||
    table.status === "accepted" ||
    table.status === "awaiting_payment" ||
    table.status === "ready"
  ) {
    return "border-[#f5a742]/45 bg-[#f5a742]/14 text-[#ffd08a]";
  }
  if (occupiedTableStatuses.has(table.status)) {
    return "border-[#d11a2a]/45 bg-[#d11a2a]/12 text-[#ffc2c8]";
  }
  return "border-[#4a4a54] bg-white/[0.06] text-[#d4d4d8]";
}

function CashierThemePresetGrid({
  value,
  onChange,
}: {
  value: CashierThemeMode;
  onChange: (theme: CashierThemeMode) => void;
}) {
  return (
    <div className="grid gap-2">
      {cashierThemePresets.map((preset) => {
        const active = value === preset.value;

        return (
          <button
            key={preset.value}
            type="button"
            className={`garage-press cashier-theme-preset flex min-h-16 items-center gap-3 rounded-md border p-2.5 text-left transition ${
              active
                ? "border-[#f5a742] bg-[#f5a742]/14 text-white"
                : "border-[#34343c] bg-white/[0.045] text-[#d6d6dc]"
            }`}
            onClick={() => onChange(preset.value)}
            aria-pressed={active}
          >
            <span className="grid grid-cols-4 gap-1">
              {preset.swatches.map((color) => (
                <span
                  key={color}
                  className="size-6 rounded-sm border border-black/20 shadow-[inset_0_1px_0_rgba(255,255,255,0.28)]"
                  style={{ backgroundColor: color }}
                />
              ))}
            </span>
            <span className="min-w-0 flex-1">
              <span className="block truncate text-sm font-black">{preset.label}</span>
              <span className="mt-0.5 block truncate text-xs opacity-80">{preset.detail}</span>
            </span>
            {active ? <Check className="size-4 shrink-0 text-[#22c55e]" /> : null}
          </button>
        );
      })}
    </div>
  );
}

function OpeningCashPresetPicker({
  value,
  onChange,
  label = "Uang modal awal di laci",
  helper = `Minimal ${currency.format(50000)}, maksimal ${currency.format(500000)}.`,
}: {
  value: string;
  onChange: (value: string) => void;
  label?: string;
  helper?: string;
}) {
  const selectedValue = Number(value);

  return (
    <div className="space-y-2">
      <p className="garage-mono text-[10px] text-[#b8b8bf]">{label}</p>
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-5">
        {openingCashPresets.map((amount) => {
          const active = selectedValue === amount;
          return (
            <button
              key={amount}
              type="button"
              onClick={() => onChange(String(amount))}
              className={`garage-press h-10 rounded-md border px-2 text-xs font-black transition ${
                active
                  ? "border-[#f5a742] bg-[#f5a742] text-[#111116]"
                  : "border-[#4a4a54] bg-white/[0.055] text-[#f4f4f5] hover:border-[#f5a742]/70"
              }`}
            >
              {currency.format(amount)}
            </button>
          );
        })}
      </div>
      <Input
        type="number"
        inputMode="numeric"
        min={50000}
        max={500000}
        step={50000}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-11 border-[#34343c] bg-white/[0.06]"
      />
      {helper ? <p className="text-xs leading-5 text-[#8f8f99]">{helper}</p> : null}
    </div>
  );
}

