function SettingsChoiceGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: Array<{ value: T; label: string; detail?: string }>;
  onChange: (value: T) => void;
}) {
  return (
    <div className="space-y-2">
      <p className="garage-mono text-[10px] text-[#b8b8bf]">{label}</p>
      <div className="grid gap-2 sm:grid-cols-2">
        {options.map((option) => {
          const active = option.value === value;
          return (
            <button
              key={option.value}
              type="button"
              className={`garage-press min-h-14 rounded-md border p-2.5 text-left transition ${
                active
                  ? "border-[#f5a742] bg-[#f5a742]/16 text-white"
                  : "border-[#34343c] bg-white/[0.045] text-[#d6d6dc] hover:border-[#f5a742]/55"
              }`}
              onClick={() => onChange(option.value)}
              aria-pressed={active}
            >
              <span className="flex items-center justify-between gap-2">
                <span className="font-semibold">{option.label}</span>
                {active ? <Check className="size-4 text-[#22c55e]" /> : null}
              </span>
              {option.detail ? (
                <span className="mt-1 block text-xs leading-4 opacity-80">{option.detail}</span>
              ) : null}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function tableAvailabilityState(
  table: TableLiveRow | null | undefined,
  liveDataReady: boolean,
): TableAvailability {
  if (!table || !liveDataReady) return "unknown";
  if (table.status === "empty" && !table.needsCleaning) return "ready";
  if (
    table.needsCleaning ||
    table.status === "needs_cleaning" ||
    occupiedTableStatuses.has(table.status)
  ) {
    return "full";
  }

  return "unknown";
}

function tableAvailabilityLabel(availability: TableAvailability) {
  if (availability === "ready") return "Ready";
  if (availability === "full") return "Penuh";
  return "Belum sinkron";
}

