                              <Input
                                value={selectedProvider.baseUrl}
                                onChange={(event) =>
                                  updateProvider(selectedProvider.provider, {
                                    baseUrl: event.target.value,
                                  })
                                }
                                className="mt-1 border-[#34343c] bg-white/[0.06]"
                              />
