            <button
              type="button"
              onClick={() => setSettingsQuery("")}
              aria-label="Bersihkan pencarian"
              className="absolute right-2 top-1/2 -translate-y-1/2 rounded p-1 text-[#8a8a93] transition-colors hover:text-white"
            >
              <X className="size-4" />
            </button>
